const TESTS={"Schouder":[{"id":"hawkins-kennedy","naam":"Hawkins-Kennedy Test","beoordeelt":"Subacromiale impingement (M. Supraspinatus pees / bursa)","waarom":"Simuleert de meest voorkomende inklemmingspositie van de supraspinatuspees onder het acromion tijdens overhead-bewegingen — zeer relevant voor overhead-sporters (zwemmen, volleybal, werpen).","uitvoering":["Cliënt zit of staat, arm 90° geflecteerd in de schouder, elleboog 90° gebogen","Trainer stabiliseert de scapula met één hand","Trainer beweegt de arm passief in endorotatie (onderarm naar binnen draaien)"],"positief":"Pijn/onbehagen in de anterolaterale schouder tijdens de endorotatie → wijst op impingement van supraspinatuspees of subacromiale bursa","negatief":"Volledige, pijnvrije endorotatie zonder klachten","gekoppeldeSpieren":["M. Supraspinatus","M. Infraspinatus"],"bronLink":"https://www.physiotutors.com/wiki/hawkins-kennedy-test/"},{"id":"empty-can","naam":"Empty Can Test (Jobe Test)","beoordeelt":"Kracht en integriteit van M. Supraspinatus","waarom":"Isoleert de Supraspinatus door de arm in de 'leegblik'-positie (duim naar beneden) te plaatsen, waarbij de Deltoideus minder kan compenseren dan bij een neutrale positie — hierdoor de meest specifieke krachttest voor deze spier.","uitvoering":["Cliënt staat, armen 90° geabduceerd, 30° horizontaal geflecteerd (in het scapulavlak), duimen naar beneden gedraaid","Trainer oefent van bovenaf neerwaartse druk uit op beide armen","Cliënt weerstaat de druk"],"positief":"Duidelijke zwakte, pijn, of het 'vallen' van de arm t.o.v. de andere zijde → wijst op Supraspinatus-pathologie (tendinopathie of ruptuur)","negatief":"Symmetrische, sterke weerstand zonder pijn","gekoppeldeSpieren":["M. Supraspinatus"],"bronLink":"https://www.physiotutors.com/wiki/empty-can-test/"},{"id":"lift-off","naam":"Lift-Off Test (Gerber's Test)","beoordeelt":"Kracht van M. Subscapularis","waarom":"De enige test die de Subscapularis isoleert in een positie waarin geen andere schouderspier de beweging kan overnemen — de hand loslaten van de rug is alleen mogelijk met actieve endorotatiekracht.","uitvoering":["Cliënt staat, hand op de onderrug (handrug tegen de lumbale wervelkolom), elleboog gebogen","Cliënt tilt de hand actief van de rug af, weg van het lichaam","Bij beperkte schoudermobiliteit: gebruik de Belly Press test als alternatief"],"positief":"Cliënt kan de hand niet van de rug tillen, of alleen met compensatie (elleboog naar achteren) → wijst op Subscapularis-ruptuur/zwakte","negatief":"Hand wordt moeiteloos enkele centimeters van de rug getild","gekoppeldeSpieren":["M. Subscapularis"],"bronLink":"https://www.physiotutors.com/wiki/lift-off-sign/"}],"Heup":[{"id":"trendelenburg","naam":"Trendelenburg Test","beoordeelt":"Functie/kracht van M. Gluteus Medius (en M. Gluteus Minimus) als bekkenstabilisator","waarom":"De Gluteus Medius is de belangrijkste frontale-vlak stabilisator van het bekken tijdens de standfase van het lopen. Bij zwakte is dit functioneel direct zichtbaar in de looppas — verklaart vaak klachten aan heup, knie of lage rug bij sporters.","uitvoering":["Cliënt staat rechtop, gewicht op één been, ander been licht gebogen los in de lucht","Trainer kijkt van achteren naar het bekken (SIAS/heupkammen als referentie)","Houd de positie 6 seconden vast","Herhaal aan de andere zijde ter vergelijking"],"positief":"Bekken aan de niet-belaste zijde zakt naar beneden → wijst op zwakte Gluteus Medius aan de belaste (standbeen) zijde. Vaak ook: Duchenne-hink of balansverlies","negatief":"Bekken blijft horizontaal, SIAS beide zijden gelijke hoogte, stabiel gedurende 6 sec","gekoppeldeSpieren":["M. Gluteus Medius","M. Gluteus Minimus","M. Tensor Fasciae Latae"],"bronLink":"https://www.physiotutors.com/wiki/trendelenburg-sign/"},{"id":"thomas","naam":"Thomas Test","beoordeelt":"Verkorting van M. Iliopsoas en M. Rectus Femoris (heupflexoren)","waarom":"Door het bekken vlak te fixeren (contralaterale heup maximaal geflecteerd tegen de borst) wordt lumbale compensatie uitgeschakeld, waardoor alleen de werkelijke lengte van de heupflexoren wordt gemeten.","uitvoering":["Cliënt ligt op de rug aan het einde van de behandeltafel","Cliënt trekt één knie actief naar de borst en houdt deze vast (fixeert bekken/lumbale wervelkolom)","Het andere been hangt vrij over de rand van de tafel","Trainer observeert hoek en positie van het hangende been"],"positief":"Dij blijft omhoog staan → verkorte M. Iliopsoas. Onderbeen strekt actief → verkorte M. Rectus Femoris. Dij beweegt naar buiten (abductie) → verkorte M. Tensor Fasciae Latae","negatief":"Dij zakt volledig horizontaal en de knie hangt ontspannen in ~90° flexie","gekoppeldeSpieren":["M. Iliopsoas","M. Rectus Femoris","M. Tensor Fasciae Latae"],"bronLink":"https://www.physiotutors.com/wiki/thomas-test/"},{"id":"faber","naam":"FABER Test (Patrick's Test)","beoordeelt":"Heupgewrichtsmobiliteit, adductor-verkorting, en SI-gewrichtsprovocatie","waarom":"De gecombineerde beweging (Flexie-ABductie-Exorotatie) ontdekt zowel gewrichtsbeperkingen als spierverkorting van de mediale heupspieren in één vloeiende test — snel en functioneel bruikbaar zonder apparatuur.","uitvoering":["Cliënt ligt op de rug","Enkel van het te testen been op de knie van het andere been plaatsen ('figuur 4'-positie)","Trainer duwt de geflecteerde knie voorzichtig richting de tafel"],"positief":"Knie blijft duidelijk hoger dan andere zijde → verkorte adductoren of gewrichtsbeperking. Pijn in de lies → heupgewrichtspathologie. Pijn in onderrug/bekken → SI-gewrichtsprobleem","negatief":"Knie zakt nagenoeg symmetrisch tot vlak bij de tafel, pijnvrij","gekoppeldeSpieren":["M. Adductor Magnus","M. Adductor Longus","M. Adductor Brevis","M. Gracilis"],"bronLink":"https://www.physiotutors.com/wiki/patricks-test/"}],"Knie":[{"id":"lachman","naam":"Lachman Test","beoordeelt":"Integriteit van de Voorste Kruisband (VKB)","waarom":"Klinisch en wetenschappelijk aangetoond als de meest sensitieve test voor VKB-letsel — lichte knieflexie (20-30°) voorkomt dat de hamstrings de anterieure translatie blokkeren, in tegenstelling tot de Anterior Drawer test bij 90°.","uitvoering":["Cliënt ligt op de rug, knie in 20-30° flexie, been ontspannen","Trainer stabiliseert het femur met één hand","Trainer trekt de tibia met de andere hand naar voren"],"positief":"Duidelijke voorwaartse verschuiving van de tibia zonder hard eindgevoel (soft end-feel) t.o.v. de andere knie → wijst op VKB-ruptuur","negatief":"Minimale translatie met een stevig, hard eindgevoel","gekoppeldeSpieren":["Hamstrings"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/wiki/lachman-test/"},{"id":"thessaly","naam":"Thessaly Test","beoordeelt":"Meniscusletsel (mediaal/lateraal)","waarom":"In tegenstelling tot de klassieke McMurray-test (liggend, passief) wordt deze test staand en belast uitgevoerd — bootst functionele, sportspecifieke rotatiebelasting na met hogere sensitiviteit/specificiteit in de praktijk.","uitvoering":["Cliënt staat op één been (te testen zijde), trainer ondersteunt eventueel de handen voor balans","Cliënt buigt de knie licht (5° en daarna 20°)","Cliënt draait romp en knie heen en weer terwijl voetcontact behouden blijft"],"positief":"Pijn in de gewrichtsspleet (mediaal of lateraal), eventueel gevoel van 'vastzitten' → wijst op meniscusscheur aan die zijde","negatief":"Vloeiende rotatie zonder pijn of mechanisch slotgevoel","gekoppeldeSpieren":["M. Popliteus"],"structuurType":"meniscus/gewricht","bronLink":"https://www.physiotutors.com/wiki/thessaly-test/"},{"id":"valgus-stress","naam":"Valgus Stress Test","beoordeelt":"Integriteit van de Mediale Collaterale Band (MCL)","waarom":"Directe, gerichte belasting van de mediale gewrichtslijn in lichte flexie (20-30°) sluit de stabiliserende rol van kniekapsel/kruisbanden grotendeels uit, waardoor specifiek de MCL wordt beoordeeld.","uitvoering":["Cliënt ligt op de rug, knie in 20-30° flexie","Trainer plaatst één hand lateraal aan de knie, de andere hand mediaal aan de enkel","Trainer oefent een valgusdruk uit (mediale opening forceren)"],"positief":"Overmatige mediale gewrichtsopening en/of pijn t.o.v. de andere knie → wijst op MCL-letsel (graad I-III)","negatief":"Minimale opening, stevig eindgevoel, geen pijn","gekoppeldeSpieren":["M. Gracilis","Hamstrings"],"structuurType":"ligamentair","bronLink":"https://www.physiotutors.com/wiki/valgus-stress-test/"}]};
